// Design Ref: §3.1 nearbyFacilities — 카카오 카테고리 검색(반경 1km), 카테고리 그룹코드: SW8(지하철), MT1(대형마트), HP8(병원), SC4(학교)
const geo = $input.first().json.documents?.[0];
if (!geo) {
  return [{ json: { ...$('New Property Webhook').first().json.body, lat: null, lng: null, nearbyFacilities: [] } }];
}
const lat = Number(geo.y);
const lng = Number(geo.x);
const categories = [
  { code: 'SW8', label: '지하철' },
  { code: 'MT1', label: '마트' },
  { code: 'HP8', label: '병원' },
  { code: 'SC4', label: '학교' },
];
const apiKey = $env.KAKAO_REST_API_KEY;
const facilities = [];
for (const cat of categories) {
  const url = `https://dapi.kakao.com/v2/local/search/category.json?category_group_code=${cat.code}&x=${lng}&y=${lat}&radius=1000&sort=distance`;
  const res = await fetch(url, { headers: { Authorization: `KakaoAK ${apiKey}` } });
  const data = await res.json();
  for (const doc of (data.documents ?? []).slice(0, 5)) {
    facilities.push({ category: cat.label, name: doc.place_name, distanceMeters: Number(doc.distance) });
  }
}
return [{ json: { ...$('New Property Webhook').first().json.body, lat, lng, nearbyFacilities: facilities } }];

// TODO: 국토교통부 실거래가 API(getRTMSDataSvcAptTrade)는 LAWD_CD(법정동코드, 전국 수천개) 매핑이 필요.
// 매핑 테이블 미보유로 1차 범위에서는 빈 배열 반환. 추후 법정동코드 테이블 확보 후 실제 호출로 교체.
// 참고: https://www.data.go.kr (국토교통부_아파트매매 실거래자료)
return [{ json: { ...$input.first().json, nearbyPrices: [] } }];

