// Design Ref: §3.3 quality_flag — 체크리스트 5항목 미만이면 재생성 플래그
const prev = $('MOLIT RTMS Lookup (TODO)').first().json;
const raw = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text ?? '{}';
let parsed;
try {
  const jsonText = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(jsonText);
} catch {
  parsed = { infrastructureSummary: '', checklist: [] };
}
const checklist = Array.isArray(parsed.checklist) ? parsed.checklist : [];
return [{
  json: {
    property_id: prev.propertyId,
    infrastructure_summary: parsed.infrastructureSummary ?? '',
    checklist,
    nearby_prices: prev.nearbyPrices ?? [],
    nearby_facilities: prev.nearbyFacilities ?? [],
    coordinates: prev.lat != null ? { lat: prev.lat, lng: prev.lng } : null,
    generated_by: 'gemini-flash',
    quality_flag: checklist.length >= 5 ? 'ok' : 'needs_regeneration',
  },
}];
